def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def heapIndexed(tree):
    vals, left, right = _links(tree)
    if not vals:
        return []
    idx = [0] * len(vals)
    for k in range(len(vals)):  # parents come before their children in level order
        if left[k] != -1:
            idx[left[k]] = 2 * idx[k] + 1
        if right[k] != -1:
            idx[right[k]] = 2 * idx[k] + 2
    out = [-1] * (max(idx) + 1)
    for k, i in enumerate(idx):
        out[i] = vals[k]
    return out
